import sys,json
# dotnet package list with slnx may output per-project JSONs; read from stdin
raw = sys.stdin.read()
# Try parsing; if it fails, it might be multiple JSON objects
try:
    data = json.loads(raw)
    projects = data.get('projects', [])
except:
    projects = []

print('=== AFTER-CPM PACKAGES ===')
for proj in projects:
    name = proj['path'].split('/')[-1]
    for fw in proj.get('frameworks', []):
        for pkg in fw.get('topLevelPackages', []):
            print(f'  {name}: {pkg[\"id\"]} {pkg.get(\"resolvedVersion\", \"?\")}')
